//! Complete HTTP/1 memory-transport control; no socket-capacity claims.
use bytes::Bytes;
use http_body_util::Full;
use hyper::{Response, StatusCode, server::conn::http1, service::service_fn};
use hyper_util::{rt::TokioIo, service::TowerToHyperService};
use maximus::{Handler, IntoResponse, Request};
use std::{
    cell::RefCell,
    convert::Infallible,
    io,
    pin::Pin,
    rc::Rc,
    sync::Arc,
    task::{Context, Poll},
    time::Instant,
};

const REQUESTS: usize = 1000;
const CONNECTIONS: usize = 1000;
const WARMUP: usize = 10;

#[derive(Clone, Copy)]
enum Kind {
    Plain,
    StaticError,
    OwnedError,
}
impl Kind {
    fn name(self) -> &'static str {
        match self {
            Self::Plain => "plain",
            Self::StaticError => "static-error",
            Self::OwnedError => "owned-error",
        }
    }
    fn status(self) -> StatusCode {
        match self {
            Self::Plain => StatusCode::OK,
            _ => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
    fn text(self) -> &'static str {
        match self {
            Self::Plain => "Hello, World!",
            _ => "handler error",
        }
    }
    fn bytes(self) -> Bytes {
        match self {
            Self::OwnedError => Bytes::from(self.text().to_owned()),
            _ => Bytes::from_static(self.text().as_bytes()),
        }
    }
}
impl Handler for Kind {
    async fn handle(&self, _: Request) -> maximus::Response {
        match self {
            Self::Plain => self.text().into_response(),
            Self::StaticError => maximus::Error::new(self.status(), self.text()).into_response(),
            Self::OwnedError => {
                maximus::Error::new(self.status(), self.text().to_owned()).into_response()
            }
        }
    }
}

struct Wire {
    input: Arc<[u8]>,
    offset: usize,
    output: Rc<RefCell<Vec<u8>>>,
}
impl Wire {
    fn read(&mut self, out: &mut [u8]) -> usize {
        let n = out.len().min(self.input.len() - self.offset);
        out[..n].copy_from_slice(&self.input[self.offset..self.offset + n]);
        self.offset += n;
        n
    }
    fn write(&mut self, bytes: &[u8]) -> usize {
        self.output.borrow_mut().extend_from_slice(bytes);
        bytes.len()
    }
    fn write_vectored(&mut self, buffers: &[io::IoSlice<'_>]) -> usize {
        let mut output = self.output.borrow_mut();
        let mut length = 0;
        for bytes in buffers {
            output.extend_from_slice(bytes);
            length += bytes.len();
        }
        length
    }
}
impl futures_util::AsyncRead for Wire {
    fn poll_read(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
        out: &mut [u8],
    ) -> Poll<io::Result<usize>> {
        Poll::Ready(Ok(self.read(out)))
    }
}
impl futures_util::AsyncWrite for Wire {
    fn poll_write_vectored(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
        buffers: &[io::IoSlice<'_>],
    ) -> Poll<io::Result<usize>> {
        Poll::Ready(Ok(self.write_vectored(buffers)))
    }
    fn poll_write(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
        bytes: &[u8],
    ) -> Poll<io::Result<usize>> {
        Poll::Ready(Ok(self.write(bytes)))
    }
    fn poll_flush(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> {
        Poll::Ready(Ok(()))
    }
    fn poll_close(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> {
        Poll::Ready(Ok(()))
    }
}
impl tokio::io::AsyncRead for Wire {
    fn poll_read(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
        out: &mut tokio::io::ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        let n = out.remaining().min(self.input.len() - self.offset);
        out.put_slice(&self.input[self.offset..self.offset + n]);
        self.offset += n;
        Poll::Ready(Ok(()))
    }
}
impl tokio::io::AsyncWrite for Wire {
    fn is_write_vectored(&self) -> bool {
        true
    }
    fn poll_write_vectored(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
        buffers: &[io::IoSlice<'_>],
    ) -> Poll<io::Result<usize>> {
        Poll::Ready(Ok(self.write_vectored(buffers)))
    }
    fn poll_write(
        mut self: Pin<&mut Self>,
        _: &mut Context<'_>,
        bytes: &[u8],
    ) -> Poll<io::Result<usize>> {
        Poll::Ready(Ok(self.write(bytes)))
    }
    fn poll_flush(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> {
        Poll::Ready(Ok(()))
    }
    fn poll_shutdown(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> {
        Poll::Ready(Ok(()))
    }
}

fn validate(output: &[u8], kind: Kind) {
    let mut rest = output;
    for index in 0..REQUESTS {
        let end = rest
            .windows(4)
            .position(|x| x == b"\r\n\r\n")
            .expect("complete response headers");
        let header = std::str::from_utf8(&rest[..end]).unwrap();
        let mut lines = header.split("\r\n");
        let mut status = lines.next().unwrap().split_whitespace();
        assert_eq!(status.next(), Some("HTTP/1.1"));
        assert_eq!(status.next(), Some(kind.status().as_str()));
        let mut close = false;
        let mut lengths = Vec::new();
        let mut content_types = Vec::new();
        for line in lines {
            let (key, value) = line.split_once(':').unwrap();
            if key.eq_ignore_ascii_case("content-length") {
                lengths.push(value.trim().parse::<usize>().unwrap());
            }
            if key.eq_ignore_ascii_case("content-type") {
                content_types.push(value.trim());
            }
            if key.eq_ignore_ascii_case("connection") {
                close |= value
                    .split(',')
                    .any(|token| token.trim().eq_ignore_ascii_case("close"));
            }
            assert!(!key.eq_ignore_ascii_case("transfer-encoding"));
        }
        assert_eq!(close, index + 1 == REQUESTS);
        assert_eq!(lengths, [kind.text().len()]);
        assert_eq!(content_types, ["text/plain; charset=utf-8"]);
        let body = &rest[end + 4..];
        assert_eq!(&body[..kind.text().len()], kind.text().as_bytes());
        rest = &body[kind.text().len()..];
    }
    assert!(rest.is_empty(), "exactly the requested response count");
}

async fn measure(engine: &str, kind: Kind) {
    let mut requests = b"GET /probe HTTP/1.1\r\nHost: localhost\r\n\r\n".repeat(REQUESTS - 1);
    requests
        .extend_from_slice(b"GET /probe HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n");
    let input: Arc<[u8]> = requests.into();
    let mut router = maximus::DynamicRouter::new(1);
    router
        .add("GET", "/probe", move |request: Request| async move {
            kind.handle(request).await
        })
        .unwrap();
    let router = Rc::new(router);
    let handler = Rc::new(kind);
    let limits = Rc::new(maximus::Limits::default());
    let shutdown = maximus_runtime::Shutdown::default();
    let axum = axum::Router::new().route(
        "/probe",
        axum::routing::get(move || async move {
            (
                kind.status(),
                [("content-type", "text/plain; charset=utf-8")],
                kind.bytes(),
            )
        }),
    );
    let service = service_fn(move |_: hyper::Request<hyper::body::Incoming>| async move {
        let mut response = Response::new(Full::new(kind.bytes()));
        *response.status_mut() = kind.status();
        response.headers_mut().insert(
            "content-type",
            hyper::header::HeaderValue::from_static("text/plain; charset=utf-8"),
        );
        Ok::<_, Infallible>(response)
    });
    let mut outputs = Vec::with_capacity(CONNECTIONS);
    let mut started = Instant::now();
    for index in 0..WARMUP + CONNECTIONS {
        if index == WARMUP {
            started = Instant::now();
        }
        let output = Rc::new(RefCell::new(Vec::new()));
        let wire = Wire {
            input: input.clone(),
            offset: 0,
            output: output.clone(),
        };
        match engine {
            "maximus" => maximus_http1::serve_futures(
                wire,
                handler.clone(),
                limits.clone(),
                shutdown.clone(),
            )
            .await
            .unwrap(),
            "dynamic" => {
                maximus_http1::serve_futures(wire, router.clone(), limits.clone(), shutdown.clone())
                    .await
                    .unwrap()
            }
            "hyper" => http1::Builder::new()
                .half_close(true)
                .serve_connection(TokioIo::new(wire), service)
                .await
                .unwrap(),
            "axum" => http1::Builder::new()
                .half_close(true)
                .serve_connection(TokioIo::new(wire), TowerToHyperService::new(axum.clone()))
                .await
                .unwrap(),
            _ => panic!("unknown engine"),
        }
        let output = Rc::try_unwrap(output).unwrap().into_inner();
        if index < WARMUP {
            validate(&output, kind);
        } else {
            outputs.push(output);
        }
    }
    let elapsed = started.elapsed();
    for output in &outputs {
        validate(output, kind);
    }
    println!(
        "{engine},{},{},{:.3}",
        kind.name(),
        REQUESTS * CONNECTIONS,
        elapsed.as_nanos() as f64 / (REQUESTS * CONNECTIONS) as f64
    );
}

fn main() {
    let engine = std::env::args().nth(1).expect("engine argument");
    println!("engine,case,requests,ns_per_request");
    match engine.as_str() {
        "maximus" | "dynamic" => {
            let runtime = maximus_runtime::WorkerConfig::default().build(0).unwrap();
            runtime.block_on(async {
                for kind in [Kind::Plain, Kind::StaticError, Kind::OwnedError] {
                    measure(&engine, kind).await;
                }
            });
        }
        "hyper" | "axum" => {
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap();
            runtime.block_on(async {
                for kind in [Kind::Plain, Kind::StaticError, Kind::OwnedError] {
                    measure(&engine, kind).await;
                }
            });
        }
        _ => panic!("unknown engine"),
    }
}

